import 'dart:async';

import 'package:audioplayers/audioplayers.dart';
import 'package:flutter/foundation.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

import '../settings/app_settings.dart';

/// Short procedural sound effects shipped under `assets/audio/<name>.wav`
/// (generated by `dart run tool/generate_sfx.dart`).
enum Sfx {
  diceRoll('dice_roll'),
  tokenStep('token_step'),
  capture('capture'),
  home('home'),
  snakeSlide('snake_slide'),
  ladderClimb('ladder_climb'),
  win('win'),
  lose('lose'),
  click('click'),
  turn('turn'),
  coin('coin'),
  levelUp('level_up'),
  chatPop('chat_pop');

  const Sfx(this.file);

  final String file;

  /// Path relative to `assets/` (audioplayers' AssetSource prefix).
  String get assetPath => 'audio/$file.wav';

  /// Effects that can overlap rapidly and get a pre-warmed pool.
  bool get pooled =>
      this == Sfx.click || this == Sfx.tokenStep || this == Sfx.diceRoll;
}

/// Plays UI and game sound effects. Honors the Sound setting; never throws.
abstract interface class AudioService {
  /// Fire-and-forget. No-op when sound is disabled.
  void play(Sfx sfx, {double volume = 1.0});

  /// Pre-loads the most frequent effects (call once after the first frame).
  Future<void> warmUp();

  Future<void> dispose();
}

/// audioplayers implementation with low-latency pools for rapid effects.
class AudioPlayersService implements AudioService {
  AudioPlayersService({required this._enabled});

  final bool Function() _enabled;
  final Map<Sfx, Future<AudioPool>> _pools = {};
  bool _contextSet = false;
  bool _disposed = false;

  /// Audio session for short game/UI effects.
  ///
  /// - iOS: `ambient` — mixes with the user's music and is silenced by the
  ///   Ring/Silent switch. (`mixWithOthers` must NOT be passed explicitly: iOS
  ///   only accepts it for playback/playAndRecord/multiRoute, and ambient
  ///   already mixes.)
  /// - Android: game/sonification usage without requesting audio focus, so
  ///   background music keeps playing.
  static AudioContext sfxAudioContext() => AudioContext(
    iOS: AudioContextIOS(category: AVAudioSessionCategory.ambient),
    android: const AudioContextAndroid(
      isSpeakerphoneOn: false,
      stayAwake: false,
      contentType: AndroidContentType.sonification,
      usageType: AndroidUsageType.game,
      audioFocus: AndroidAudioFocus.none,
    ),
  );

  Future<void> _ensureContext() async {
    if (_contextSet) return;
    _contextSet = true;
    try {
      await AudioPlayer.global.setAudioContext(sfxAudioContext());
    } catch (e) {
      debugPrint('audio: context not set ($e)');
    }
  }

  Future<AudioPool> _pool(Sfx sfx) => _pools.putIfAbsent(
    sfx,
    () => AudioPool.create(
      source: AssetSource(sfx.assetPath),
      maxPlayers: sfx.pooled ? 4 : 2,
      playerMode: PlayerMode.lowLatency,
      audioContext: sfxAudioContext(),
    ),
  );

  @override
  Future<void> warmUp() async {
    try {
      await _ensureContext();
      await Future.wait([
        for (final s in Sfx.values.where((s) => s.pooled)) _pool(s),
      ]);
    } catch (e) {
      debugPrint('audio: warm-up failed ($e)');
    }
  }

  @override
  void play(Sfx sfx, {double volume = 1.0}) {
    if (_disposed || !_enabled()) return;
    unawaited(_play(sfx, volume));
  }

  Future<void> _play(Sfx sfx, double volume) async {
    try {
      await _ensureContext();
      final pool = await _pool(sfx);
      await pool.start(volume: volume.clamp(0.0, 1.0));
    } catch (e) {
      // A missing codec or audio focus loss must never break gameplay.
      _pools.remove(sfx);
      debugPrint('audio: ${sfx.file} failed ($e)');
    }
  }

  @override
  Future<void> dispose() async {
    _disposed = true;
    for (final p in _pools.values) {
      try {
        await (await p).dispose();
      } catch (_) {}
    }
    _pools.clear();
  }
}

/// Silent implementation (tests, widget previews).
class SilentAudioService implements AudioService {
  final List<Sfx> played = [];

  @override
  void play(Sfx sfx, {double volume = 1.0}) => played.add(sfx);

  @override
  Future<void> warmUp() async {}

  @override
  Future<void> dispose() async {}
}

final audioServiceProvider = Provider<AudioService>((ref) {
  final service = AudioPlayersService(
    enabled: () => ref.read(settingsControllerProvider).soundEnabled,
  );
  ref.onDispose(service.dispose);
  return service;
});
